import{_ as a,c as o,o as t,aj as r}from"./chunks/framework.BlveriQe.js";const m=JSON.parse('{"title":"Interface: PromptsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/PromptsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/PromptsAPI.md"}'),c={name:"reference/js-bao-wss-client/api/interfaces/PromptsAPI.md"};function s(d,e,i,n,p,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / PromptsAPI</p><h1 id="interface-promptsapi" tabindex="-1">Interface: PromptsAPI <a class="header-anchor" href="#interface-promptsapi" aria-label="Permalink to “Interface: PromptsAPI”">​</a></h1><p>Prompts API, available as <code>client.prompts</code>. Executes prompts configured server-side for the app, identified by prompt key.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="execute" tabindex="-1">execute() <a class="header-anchor" href="#execute" aria-label="Permalink to “execute()”">​</a></h3><blockquote><p><strong>execute</strong>&lt;<code>V</code>, <code>R</code>&gt;(<code>promptKey</code>, <code>options</code>): <code>Promise</code>&lt;<a href="./ExecutePromptResult.html"><code>ExecutePromptResult</code></a>&lt;<code>R</code>&gt;&gt;</p></blockquote><p>Execute a prompt by key and return the result.</p><p>The optional generics are additive. <code>V</code> types the <code>variables</code> bag and <code>R</code> types <code>rawResponse</code>. Both default to today&#39;s untyped shapes, so existing callers are unaffected.</p><p>Every prompt carries an <code>accessRule</code> deciding who may execute it. A refusal rejects with a <code>JsBaoApiError</code> whose <code>status</code> is <code>403</code> and whose <code>code</code> is <code>&quot;PROMPT_ACCESS_DENIED&quot;</code> — including when the prompt has no rule stored at all, which denies every caller who is not an app admin or owner. A prompt that is not in service rejects with a <code>400</code> whose <code>code</code> is <code>&quot;PROMPT_NOT_EXECUTABLE&quot;</code>. Availability is a single server-owned <code>status</code>: only an <code>active</code> prompt executes here, and <code>primitive prompts enable</code> puts an inactive one back in service.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to “V”">​</a></h5><p><code>V</code> <em>extends</em> <code>object</code> = <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p><h5 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to “R”">​</a></h5><p><code>R</code> = <code>unknown</code></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="promptkey" tabindex="-1">promptKey <a class="header-anchor" href="#promptkey" aria-label="Permalink to “promptKey”">​</a></h5><p><code>string</code></p><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./ExecutePromptOptions.html"><code>ExecutePromptOptions</code></a>&lt;<code>V</code>&gt;</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./ExecutePromptResult.html"><code>ExecutePromptResult</code></a>&lt;<code>R</code>&gt;&gt;</p>',23)])])}const u=a(c,[["render",s]]);export{m as __pageData,u as default};
